mapper.select:
	 select *
from yh_pressure_evaluate
where User_Code=#{usercode} and Id=#{id}

SELECT CASE WHEN ue.gender = 1 THEN '男' ELSE '女' END AS sex , CASE pe.Evaluate_Type WHEN 1 THEN 'A型性格' WHEN 2 THEN 'PSTRI压力' WHEN 3 THEN '心理健康' ELSE '' END AS assessmentContent, pe.Id as id,pe.Evaluate_Score AS evaluateScore ,pe.Evaluate_Date AS assessmentTime,pe.Evaluate_Type AS assessmentType FROM yh_pressure_evaluate AS pe INNER JOIN `yh_user_reginfo` AS ue ON pe.User_code=ue.user_code
and pe.user_code=#{usercode}
AND pe.Evaluate_Date BETWEEN #{strTime} AND #{endTime}
AND pe.Evaluate_Type=#{type}
ORDER BY pe.Evaluate_Date DESC

SELECT ue.user_code AS usercode,ue.`user_name` AS username,ue.`name`,CASE WHEN ue.gender = 1 THEN '男' ELSE '女' END AS sex, CASE pe.Evaluate_Type WHEN 1 THEN 'A型性格' WHEN 2 THEN 'PSTRI压力' WHEN 3 THEN '心理健康' ELSE '' END AS assessmentContent,pe.Evaluate_Score AS evaluateScore ,pe.Evaluate_Date AS assessmentTime,pe.Evaluate_Type AS assessmentType FROM yh_pressure_evaluate AS pe LEFT JOIN `yh_user_reginfo` AS ue ON pe.User_code=ue.user_code LEFT JOIN `yh_user_make_card` AS ma ON ma.user_code=ue.user_code WHERE ma.doctor=(SELECT id FROM `yh_user_admin_info` WHERE user_code=#{usercode})
AND pe.Evaluate_Type=#{type}
AND ue.name LIKE CONCAT('%',#{nameLike},'%')
AND ue.user_name LIKE CONCAT('%',#{usernameLike},'%')
AND pe.Evaluate_Date BETWEEN #{strTime} AND #{endTime}
ORDER BY pe.Evaluate_Date DESC

mapper.update:
update yh_pressure_evaluate
Evaluate_Data = #{evaluateData}, Evaluate_Type = #{evaluateType}, Evaluate_Score = #{evaluateScore}, User_Code = #{userCode}, Evaluate_Date = #{evaluateDate}, Do_Date = #{doDate}, Is_Del = #{isDel}, Evaluate_select = #{evaluateSelect},
where Id = #{id}
